/**
 * Localized templates for the IDE Understand feature's DETERMINISTIC fallback
 * summary (the sentence shown for a file the semantic LLM pass never reached).
 *
 * The semantic summaries are generated by the model in the user's display
 * language already; this module keeps the cheap, no-credit fallback summaries in
 * the SAME language so a long-tail file never shows an English sentence inside
 * an otherwise-localized graph. Pure data + tiny formatters — no I/O, no React.
 *
 * Code identifiers (symbol names, file labels) are NEVER translated; only the
 * connective prose is localized. Languages mirror the app's 9 UI locales; an
 * unknown locale falls back to English.
 *
 * Process boundary: shared module (Main builder imports it). No DOM/Node APIs.
 */

import type { ArchLayer } from './understandTypes';

/** The set of localized strings + formatters needed for one fallback summary. */
export type FallbackStrings = {
  /** Plain role phrase per architectural layer. */
  role: Record<ArchLayer, string>;
  /** Compose the leading clause: `label` is a `lang` file that `role`. */
  base: (label: string, langWord: string, role: string) => string;
  /** Compose the "declares X, Y, Z (+N more)" clause from up-to-3 names + extra. */
  declares: (names: string[], more: number) => string;
  /** Compose the "imported by N files" clause. */
  importedBy: (count: number) => string;
};

/** Normalize an i18n language tag to one of our supported locale keys. */
export const normalizeLocale = (lang: string | undefined): SupportedLocale => {
  if (!lang) return 'en';
  const lower = lang.toLowerCase();
  if (lower.startsWith('vi')) return 'vi';
  if (lower.startsWith('zh')) return lower.includes('tw') || lower.includes('hant') ? 'zh-TW' : 'zh-CN';
  if (lower.startsWith('ja')) return 'ja';
  if (lower.startsWith('ko')) return 'ko';
  if (lower.startsWith('ru')) return 'ru';
  if (lower.startsWith('tr')) return 'tr';
  if (lower.startsWith('uk')) return 'uk';
  return 'en';
};

/** The locale keys this module provides fallback templates for. */
export type SupportedLocale = 'en' | 'vi' | 'zh-CN' | 'zh-TW' | 'ja' | 'ko' | 'ru' | 'tr' | 'uk';

const en: FallbackStrings = {
  role: {
    api: 'exposes an API surface (routes / handlers / endpoints)',
    service: 'holds business logic / service-layer behaviour',
    data: 'defines data models, schema, or persistence access',
    ui: 'renders user interface',
    util: 'provides shared utility / helper functionality',
    config: 'configures the project / build / tooling',
    test: 'contains tests or fixtures',
    unknown: 'is part of the codebase',
  },
  base: (label, langWord, role) => `\`${label}\` is a ${langWord}file that ${role}.`,
  declares: (names, more) =>
    more > 0 ? ` It declares ${names.join(', ')}, and ${more} more.` : ` It declares ${names.join(', ')}.`,
  importedBy: (count) => ` It is imported by ${count} other file${count === 1 ? '' : 's'}.`,
};

