/** All locale string tables, keyed by supported locale. */
const TABLES: Record<SupportedLocale, FallbackStrings> = { en, vi, 'zh-CN': zhCN, 'zh-TW': zhTW, ja, ko, ru, tr, uk };

/** Get the fallback string table for a language tag (English when unknown). */
export const fallbackStringsFor = (lang: string | undefined): FallbackStrings => TABLES[normalizeLocale(lang)];

/**
 * The human language NAME (in English) for a BCP-47-ish tag, used to instruct
 * the LLM which language to write its summaries/overview in. Unknown tags
 * default to English.
 */
export const languageNameForPrompt = (lang: string | undefined): string => {
  const names: Record<SupportedLocale, string> = {
    en: 'English',
    vi: 'Vietnamese',
    'zh-CN': 'Simplified Chinese',
    'zh-TW': 'Traditional Chinese',
    ja: 'Japanese',
    ko: 'Korean',
    ru: 'Russian',
    tr: 'Turkish',
    uk: 'Ukrainian',
  };
  return names[normalizeLocale(lang)];
};
